package store.cadera.cdrjobs.service;
import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.potion.*;import store.cadera.cdrjobs.CdrJobsPlugin;import store.cadera.cdrjobs.data.*;import store.cadera.cdrjobs.model.*;import store.cadera.cdrjobs.util.Colors;import java.util.*;import java.util.concurrent.ConcurrentHashMap;
public final class LumberjackService {public static final String JOB="LUMBERJACK",GROVE_RHYTHM="lumberjack_grove_rhythm";private final CdrJobsPlugin plugin;private final Database db;private final ProfessionStore store;private final Map<UUID,Long> active=new ConcurrentHashMap<>();private final Map<UUID,Streak> streaks=new ConcurrentHashMap<>();public LumberjackService(CdrJobsPlugin p,Database d,ProfessionStore s){plugin=p;db=d;store=s;}public int rank(Player p,LumberjackSkill s){return store.getSkillRank(p.getUniqueId(),s.key());}
 public boolean tryUpgrade(Player p,LumberjackSkill s){int r=rank(p,s);if(r>=s.maxRank()){msg(p,"max-skill");return false;}if(db.getProgress(p.getUniqueId(),JobType.LUMBERJACK).level()<s.requiredLevel()){msg(p,"skill-requirement");return false;}if(s.prerequisite()!=null&&rank(p,s.prerequisite())<s.prerequisiteRank()){msg(p,"skill-requirement");return false;}if(s==LumberjackSkill.GROVE_RHYTHM&&!timberComplete(p)){p.sendMessage(Colors.color(plugin.prefix()+plugin.message("trial-required").replace("%trial%","Trial of Timber")));return false;}if(s==LumberjackSkill.OATH_YGGDRASIL&&(rank(p,LumberjackSkill.FORESTS_FAVOR)<3||rank(p,LumberjackSkill.SPIRITWOOD)<3||!groveComplete(p))){msg(p,"skill-requirement");return false;}if(db.getFateEssence(p.getUniqueId())<s.essenceCost()){msg(p,"not-enough-essence");return false;}db.addFateEssence(p.getUniqueId(),-s.essenceCost());store.setSkillRank(p.getUniqueId(),s.key(),r+1);p.sendMessage(Colors.color(plugin.prefix()+plugin.message("skill-unlocked").replace("%skill%",s.displayName()).replace("%rank%",String.valueOf(r+1))));return true;}
 public long applyXp(Player p,long base){double m=1.0+rank(p,LumberjackSkill.TIMBERBORN)*.05+rank(p,LumberjackSkill.WHISPERING_AXE)*.05+rank(p,LumberjackSkill.SPIRITWOOD)*.06;if(rank(p,LumberjackSkill.OATH_YGGDRASIL)>0)m+=.20;long xp=Math.max(1,Math.round(base*m));int favor=rank(p,LumberjackSkill.FORESTS_FAVOR);if(favor>0&&Math.random()<favor*.04)xp*=2;Long until=active.get(p.getUniqueId());if(until!=null){if(until>System.currentTimeMillis()){double b=Math.max(0,plugin.getConfig().getDouble("lumberjack.abilities.grove-rhythm.xp-bonus-percent",25));xp=Math.max(1,Math.round(xp*(1+b/100)));}else active.remove(p.getUniqueId());}return xp;}
 public void recordChop(Player p,boolean elder){long logs=store.incrementCounter(p.getUniqueId(),JOB,"logs",1);if(elder)store.incrementCounter(p.getUniqueId(),JOB,"elder_logs",1);if(!timberComplete(p)&&logs>=timberTarget()){store.setFlag(p.getUniqueId(),JOB,"trial_timber",true);msg(p,"trial-timber-complete");}if(!groveComplete(p)&&logs>=groveLogTarget()&&elderLogs(p)>=groveElderTarget()){store.setFlag(p.getUniqueId(),JOB,"trial_grove",true);msg(p,"trial-grove-complete");}if(rank(p,LumberjackSkill.IRONBARK)>0){long now=System.currentTimeMillis();Streak old=streaks.get(p.getUniqueId());int count=old==null||now-old.last>60000?1:old.count+1;if(count>=20){p.addPotionEffect(new PotionEffect(PotionEffectType.RESISTANCE,100,0,true,false,true));count=0;}streaks.put(p.getUniqueId(),new Streak(count,now));}}
 public boolean activate(Player p){if(rank(p,LumberjackSkill.GROVE_RHYTHM)<=0){msg(p,"lumberjack-ability-locked");return false;}long now=System.currentTimeMillis(),ready=store.getAbilityReadyAt(p.getUniqueId(),GROVE_RHYTHM);if(ready>now){p.sendMessage(Colors.color(plugin.prefix()+plugin.message("lumberjack-ability-cooldown").replace("%seconds%",String.valueOf((ready-now+999)/1000))));return false;}int dur=Math.max(1,plugin.getConfig().getInt("lumberjack.abilities.grove-rhythm.duration-seconds",20)),cd=Math.max(dur,plugin.getConfig().getInt("lumberjack.abilities.grove-rhythm.cooldown-seconds",300));active.put(p.getUniqueId(),now+dur*1000L);store.setAbilityReadyAt(p.getUniqueId(),GROVE_RHYTHM,now+cd*1000L);p.addPotionEffect(new PotionEffect(PotionEffectType.HASTE,dur*20,0,true,false,true));p.playSound(p.getLocation(),Sound.BLOCK_WOOD_BREAK,1,0.8f);p.sendMessage(Colors.color(plugin.prefix()+plugin.message("grove-rhythm-activated").replace("%duration%",String.valueOf(dur))));return true;}
 public long logs(Player p){return store.getCounter(p.getUniqueId(),JOB,"logs");}public long elderLogs(Player p){return store.getCounter(p.getUniqueId(),JOB,"elder_logs");}public boolean timberComplete(Player p){return store.getFlag(p.getUniqueId(),JOB,"trial_timber");}public boolean groveComplete(Player p){return store.getFlag(p.getUniqueId(),JOB,"trial_grove");}public int timberTarget(){return Math.max(1,plugin.getConfig().getInt("lumberjack.trials.trial-of-timber.logs",750));}public int groveLogTarget(){return Math.max(1,plugin.getConfig().getInt("lumberjack.trials.trial-of-ancient-grove.logs",3000));}public int groveElderTarget(){return Math.max(1,plugin.getConfig().getInt("lumberjack.trials.trial-of-ancient-grove.elder-logs",300));}private void msg(Player p,String k){p.sendMessage(Colors.color(plugin.prefix()+plugin.message(k)));}private record Streak(int count,long last){}
}
